// Üretilen dosya: tool/ozgun/uret.py. Sanat · Türk ve İslam sanatları (hat, tezhip, minyatür, ebru, çini, halı, Mimar Sinan) (zor).
const ozArt3Zor = <(String, String, List<String>, String)>[
  ('Kâğıda iz bırakmadan satır çizgilerini belirlemek için iplerin gerildiği karton araç hangisidir?', 'Mıstar', ['Mühre', 'Makta', 'Divit'], 'Mıstar, kartona belirli aralıklarla gerilmiş iplerden oluşur; üzerine kâğıt bastırılınca hafif satır izleri çıkar.'),
  ('Aklâm-ı sitte içinde birbirinin küçük ve inceltilmiş biçimi sayılan yazı çifti hangisidir?', 'Muhakkak ve reyhânî', ['Sülüs ve talik', 'Nesih ve kûfi', 'Nesih ve murabba kûfi'], 'Altı kalem üç çift olarak düşünülür: sülüs-nesih, muhakkak-reyhânî, tevkî-rikâ; reyhânî muhakkakın küçük boyutudur.'),
  ('Hat terminolojisinde \'gubari\' sözcüğü bir yazının hangi özelliğini anlatır?', 'Toz zerresi gibi çok küçük yazılmış olmasını', ['Yalnız altın mürekkeple yazılmış olmasını', 'İki yönlü simetrik yazılmasını', 'Sadece noktasız yazılmasını'], 'Gubar \'toz\' anlamındadır; gubari yazı çok ince kalemle, minicik harflerle yazılır ve güvercinle gönderilen mektuplarda da kullanılmıştır.'),
  ('Muhakkak yazısının Osmanlı döneminde özellikle hangi kullanımda tercih edildiği bilinir?', 'Büyük boy mushaflarda ve besmelelerde', ['Divan kalemindeki fermanlarda', 'Gizli devlet yazışmalarında', 'Günlük ticari senetlerde'], 'Muhakkak geniş, düz ve heybetli harfleriyle özellikle büyük boy mushaflarda ve besmele yazımında kullanılmıştır.'),
  ('Tevkî yazısının adının kaynağı olan \'tevkî\' sözcüğü neyle ilişkilidir?', 'Belgelerin imzalanıp onaylanmasıyla', ['Saray kumaşlarının dokunmasıyla', 'Cami minarelerinin süslenmesi işiyle', 'Kur\'an tilavetiyle'], 'Tevkî, hükümdar imzası ve onayı anlamına gelir; bu yazı resmî belge ve imza yazılarında kullanılmıştır.'),
  ('Aklâm-ı sitte arasında, tevkînin daha küçük ve icazetnamelerde sık kullanılan biçimi hangisidir?', 'Rikâ', ['Rik\'a', 'Reyhânî', 'Gubari'], 'Aklâm-ı sittedeki rikâ, tevkînin küçük kalemidir ve özellikle icazetnamelerde kullanılır; 19. yüzyıl Osmanlı rik\'ası ile karıştırılmamalıdır.'),
  ('Bir öğrenci \'rikâ\' ile \'rik\'a\' adlarının aynı yazıyı gösterdiğini düşünüyor. Bu düşünce neden yanlıştır?', 'Rikâ altı kalemden biridir; rik\'a sonradan gelişen Osmanlı yazısıdır', ['İkisi de aynı yazıdır ama biri yalnız renkli mürekkeple yazılır', 'Rik\'a Arap, rikâ Fars yazısıdır ve aynı kökten değildir', 'Rikâ yalnız kûfi harflerle yazılır'], 'Rikâ klasik altı kalemden biridir; rik\'a 19. yüzyılda Osmanlı\'da gündelik yazışma için sadeleştirilmiş, hızlı bir yazı olarak gelişmiştir.'),
  ('Selçuklu taş kitabelerinde harflerin dikey uzantılarının birbirine geçerek düğüm ve örgü oluşturduğu yazı türü hangisidir?', 'Örgülü kûfi', ['Gubari nesih', 'Celi divani', 'Şikeste talik'], 'Örgülü kûfide elif ve lam gibi dikey harfler birbirine dolanır; Anadolu Selçuklu mimarisinde sık rastlanır.'),
  ('Erken dönem kûfi mushaflarda noktalar ve harekeler başlangıçta nasıl gösterilmiştir?', 'Renkli mürekkeple konan noktalarla', ['Altın varakla kaplanan harflerle', 'Hiç gösterilmeyip ayrı bir kitapta verilerek', 'Satır altına yazılan Latin harfleriyle'], 'Erken mushaflarda harekeler genellikle kırmızı ya da başka renkte noktalarla gösterilmiş, böylece siyah harflerden ayrılmıştır.'),
  ('Osmanlı maliye kayıtlarında kullanılan, sayıların ve kelimelerin kısaltılmış işaretlerle yazıldığı, okunması özel eğitim gerektiren yazı türü hangisidir?', 'Siyakat', ['Reyhânî', 'Nestalik', 'Yapraklı kûfi'], 'Siyakat, maliye defterlerinde kullanılan ve sahteciliği zorlaştıran şifreli nitelikte bir yazıdır.'),
  ('Talik yazının iri boyutlu, levha ve kitabelerde kullanılan biçimini 19. yüzyılda zirveye taşıyan ve celi talikte örnek alınan hattat hangisidir?', 'Sâmi Efendi', ['Yâkut el-Müsta\'sımî', 'İbn Mukle', 'Mîr Ali Tebrizî'], 'Sâmi Efendi celi talik ve celi sülüste büyük bir üstattır; İstanbul\'daki pek çok çeşme ve türbe kitabesi onun elinden çıkmıştır.'),
  ('İbn Mukle\'den sonra onun kurallarını güzelleştirip geliştiren, 11. yüzyıl Bağdat hattatı kimdir?', 'İbn Bevvâb', ['Mîr İmâd', 'Mustafa Râkım', 'Ahmed Karahisârî'], 'İbn Bevvâb, İbn Mukle\'nin sistemini estetik açıdan olgunlaştırmış; elinden çıkan bir mushaf günümüze ulaşmıştır.'),
  ('Ahmed Karahisârî\'nin en ünlü eserlerinden biri sayılan, kelimelerin tek bir kalem hareketiyle birbirine bağlandığı yazı örneği hangisidir?', 'Tek hamlede yazılmış besmele', ['Ayasofya\'nın büyük levhaları', 'II. Mahmud tuğrası', 'Hilye-i şerife formu'], 'Karahisârî\'nin harflerin kesintisiz bağlandığı besmelesi, hat tarihinin ünlü örnekleri arasındadır.'),
  ('Ahmed Karahisârî\'nin ekolünün sınırlı kalıp Şeyh Hamdullah ekolünün yaygınlaşmasının temel nedeni nedir?', 'Karahisârî üslubunu izleyen öğrencilerin az olması', ['Karahisârî\'nin eserlerinin saray tarafından yasaklanması', 'Şeyh Hamdullah\'ın yalnız kûfi yazması', 'Karahisârî\'nin İran\'a göç etmesi'], 'Karahisârî üslubu, evlatlığı Hasan Çelebi gibi birkaç takipçiden sonra sürmemiş; Şeyh Hamdullah ekolü ise meşk zinciriyle yayılmıştır.'),
  ('Klasik hilye levhasında sayfanın en üstünde yer alan ve besmelenin yazıldığı bölüme ne ad verilir?', 'Baş makamı', ['Etek', 'Koltuk', 'Hilâl'], 'Hilye düzeninde en üstte besmelenin bulunduğu baş makamı, altında göbek, ortasında hilâl, kenarlarda köşeler ve altta etek bulunur.'),
  ('Hâfız Osman\'ın yazdığı mushafların Osmanlı ve İslam dünyasında yaygınlaşmasında 19. yüzyılda hangi gelişme belirleyici olmuştur?', 'Taş baskı yöntemiyle çoğaltılması', ['Fotoğraf makinesinin icadı', 'Kâğıdın İstanbul\'da ilk kez üretilmesi', 'Matbaanın yasaklanması'], 'Hâfız Osman mushafları 19. yüzyılda taş baskıyla çoğaltılarak geniş kitlelere ulaşmıştır.'),
  ('Hâfız Osman\'ın hilye düzenini oluşturmasının hat sanatına en önemli katkısı hangisidir?', 'Yazıyla yapılan bir Peygamber portresini kalıcı bir levha formuna sokması', ['Hilye metnini ilk kez Arapçadan Türkçeye çevirerek yaygınlaştırması', 'Hilyeyi yalnız minyatürle süsleme kuralı getirmesi', 'Hilye yazımını devlet tekeline alması'], 'Figürlü tasvir yerine yazıyla anlatılan vasıflar, Hâfız Osman\'ın düzeniyle evlere asılan bir levha geleneğine dönüşmüştür.'),
  ('Hat tarihinde \'Hâfız Osman nesihte ne ise o da celi sülüste odur\' sözüyle övülen hattat kimdir?', 'Mustafa Râkım', ['Yâkut el-Müsta\'sımî', 'İbn Mukle', 'Necmeddin Okyay'], 'Mustafa Râkım celide, Hâfız Osman ise nesih ve aklâmda zirve kabul edilir.'),
  ('Bir hat meraklısı İstanbul\'da 19. yüzyılda yapılmış bir çeşmenin celi talik kitabesini incelerken imzayı görmeden, istifin olgunluğu nedeniyle ustasını tahmin etmeye çalışıyor. Hangi hattat en olası adaydır?', 'Sâmi Efendi', ['Yâkut el-Müsta\'sımî', 'İbn Bevvâb', 'Ahmed Karahisârî'], '19. yüzyılda celi talik kitabeleriyle öne çıkan isim Sâmi Efendi\'dir; diğerleri farklı yüzyıllarda yaşamıştır.'),
  ('Osmanlı talik geleneğinin İran nestalikinden ayrışarak bağımsız bir üslup kazanmasında belirleyici olan hattat aile hangisidir?', 'Yesârî ve oğlu Yesârîzâde', ['Şeyh Hamdullah ve damadı', 'Mustafa Râkım ve kardeşi', 'Karahisârî ve evlatlığı'], '18. yüzyılda Yesârî ve oğlu Yesârîzâde ile Osmanlı talikinin kendine özgü kuralları belirlenmiştir.'),
  ('Bir kıtanın köşelerinde, büyük satır ile küçük satırlar arasında kalan üçgen boşluklara ne ad verilir ve bunlar genellikle nasıl doldurulur?', 'Koltuk; tezhiple süslenir', ['Etek; ayetle yazılır', 'Cetvel; altın çizgiyle kapatılır', 'Kenar suyu; ebruyla kaplanır'], 'Kıtadaki koltuklar, sülüs satırının boş bıraktığı köşelerdir; çoğunlukla tezhiple doldurulur.'),
  ('Tuğrada padişahın adının ve babasının adının yazıldığı, en alttaki temel bölüme ne ad verilir?', 'Sere', ['Beyze', 'Tuğ', 'Kol'], 'Sere tuğranın alt kısmıdır; ad ve \'muzaffer daima\' ibaresi burada yer alır.'),
  ('Tuğranın sağ tarafına uzanan, beyzelerin devamı olan iki paralel çizgiye ne denir?', 'Kol', ['Tuğ', 'Zülfe', 'Sere'], 'Beyzelerin sağa doğru uzanan devamı kol olarak adlandırılır; uçları hançer biçiminde sonlanır.'),
  ('Tuğralar Osmanlı\'da hangi görevli tarafından çekilirdi?', 'Nişancı', ['Defterdar', 'Kazasker', 'Reisülküttap'], 'Tuğrayı belgeye çekmek nişancının göreviydi; tuğrakeş adı verilen hattatlar da bu işte uzmanlaşırdı.'),
  ('Bir tarihçi bir fermandaki tuğranın sere kısmında \'Mahmud Han bin Abdülhamid\' yazdığını okuyor. Bu tuğra hangi padişaha aittir?', 'II. Mahmud', ['I. Mahmud', 'II. Abdülhamid', 'I. Abdülhamid'], 'Tuğrada padişahın kendi adı ve babasının adı yazılır; babası I. Abdülhamid olan Mahmud, II. Mahmud\'dur.'),
  ('Bir hattatın icazet almadan eserine imza atmasının gelenekte hoş karşılanmamasının nedeni nedir?', 'İmza hakkının hocaların onayıyla kazanılması', ['İmza atma yetkisinin yalnız padişaha ait sayılması', 'İmzalı eserlerin satılamaması', 'İmza atmanın dinen yasak olması'], 'Gelenekte imza, sanatta yetkinliğin hocalar tarafından onaylanmasının göstergesidir; eserin altına \'ketebe\' (yazdı) diyerek imza atabilmek icazete bağlıdır.'),
  ('Taş kitabelerde hattatın kâğıda yazdığı yazının taşa aktarılmasında kullanılan geleneksel yöntem hangisidir?', 'Kâğıttaki yazının delinip kalıp olarak taşa aktarılması', ['Yazının taşa doğrudan fırçayla yağlıboya ile çizilmesi', 'Harflerin dökme demirden yapılıp taşın yüzeyine çakılması', 'Yazının fotoğrafla taşa basılması'], 'Hattatın yazısı iğneyle delinir (kalıp), toz serpilerek taşa aktarılır; hakkâk bu çizgileri oyarak kabartma yazı oluşturur.'),
  ('Bir yapının kitabesinde \'amel-i\' ibaresinin ardından bir ad yazıldığı görülüyor. Bu ad büyük olasılıkla kime aittir?', 'Yapıyı yapan ustaya ya da mimara', ['Yapıyı yaptıran hükümdara', 'Kitabeyi okuyacak imama', 'Yapının vakfını yöneten mütevelliye'], '\'Amel\' iş, eser demektir; \'amel-i ...\' ibaresi eseri yapan ustanın adını bildirir. Yaptıranı ise genellikle \'bina\' ya da \'emr\' ifadeleri belirtir.'),
  ('Kâğıt üzerine altın tozlarının serpilmesiyle yapılan ve \'altın serpme\' anlamına gelen tezhip uygulaması hangisidir?', 'Zerefşan', ['Halkâr', 'Tahrir', 'Silkme'], 'Zerefşan, altının kâğıt yüzeyine serpilerek parıltılı bir zemin oluşturulmasıdır.'),
  ('Bir müzehhip, tezhibin sayfa kenarına doğru dışarı taşan ince ışın çizgileri çizecektir. Bu çizgilere ne ad verilir?', 'Tığ', ['Zencerek', 'Cetvel', 'Pafta'], 'Tığlar tezhibin dış kenarından sayfaya yayılan ince, ışın gibi çizgilerdir.'),
  ('Bir motif kurgusunda helezon biçiminde dönen sap ve dallar üzerine çiçek ve yaprakların yerleştirildiği düzene ne ad verilir?', 'Helezonik kompozisyon', ['Dörtgen ızgaralı düzen', 'Simetrik pafta düzeni', 'Dendan düzeni'], 'Tezhipte klasik kompozisyonların temelini helezon dallar oluşturur; motifler bu dallar üzerinde yer alır.'),
  ('Tezhipte sayfa kenarlarını çevreleyen, tekrar eden motiflerle oluşturulmuş ince bordürlere ne ad verilir?', 'Zencerek', ['Tığ', 'Koltuk', 'Hatime'], 'Zencerek zincir gibi tekrarlanan desenli ince şeritlerdir; tezhip alanını ya da yazıyı çevreler.'),
  ('Klasik Osmanlı tezhibi ile 18. yüzyıl sonrası barok-rokoko tezhip karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Klasik tezhipte motifler düz ve stilize, barokta gölgeli ve hacimlidir', ['Barok tezhipte altın hiç kullanılmaz, klasik tezhipte ise yalnız altın kullanılır', 'Klasik tezhip yalnız ciltte, barok yalnız levhada uygulanır', 'İkisinde de figürlü insan tasviri zorunludur'], 'Klasik dönemde iki boyutlu, stilize bir anlayış hâkimken barok etkiyle gölge, hacim ve doğal görünüş öne çıkmıştır.'),
  ('Bir müzehhip, uzun ve uçları kıvrık bir yaprağın içinde küçük çiçeklerin barındığı, dinamik bir saz kompozisyonu çiziyor. Bu çalışma hangi Osmanlı ustasının üslubunu izler?', 'Şahkulu', ['Levnî', 'Matrakçı Nasuh', 'Ali Üsküdarî'], 'Saz yolu üslubunun öncüsü, Kanuni döneminde nakkaşhaneyi yöneten Şahkulu\'dur.'),
  ('19. yüzyıl sonu ve 20. yüzyılda bozulan tezhip geleneğini klasik örnekleri inceleyerek yeniden canlandıran, tıp tarihçisi de olan kişi kimdir?', 'Süheyl Ünver', ['Hamid Aytaç', 'Mustafa Düzgünman', 'Necmeddin Okyay'], 'A. Süheyl Ünver klasik dönem eserlerinden çizimler yaparak tezhip ve süsleme sanatlarını öğrencilerine aktarmıştır.'),
  ('El yazması kitaplarda, metnin başlamasından önce gelen ve çoğunlukla kitabın adının ya da sahibinin bilgisinin bir şemse içinde verildiği sayfa hangisidir?', 'Zahriye', ['Hatime', 'Serlevha', 'Ketebe'], 'Zahriye kitabın başındaki boş sayfa yüzüdür; sıklıkla şemse biçiminde tezhiple süslenir.'),
  ('Mushafların kenar boşluklarında, cüz, hizb ya da secde yerlerini gösteren tezhipli yuvarlak işaretlere ne ad verilir?', 'Kenar gülü', ['Ketebe kaydı', 'Zahriye', 'Serlevha'], 'Kenar gülleri okuyucunun cüz, hizb veya secde yerlerini kolayca bulmasını sağlar.'),
  ('Bir öğrenci el yazmasında metnin bulunduğu alanın dışındaki boş kenarlara \'pervaz\' adı verildiğini öğreniyor. Pervaz alanında hangi tezhip tekniğinin uygulanması en yaygındır?', 'Halkâr', ['Tahrir', 'Silkme', 'Murakka'], 'Pervaz ve kıta kenarları genellikle tek renk altınla yapılan halkârla süslenir.'),
  ('Ehl-i hiref defterlerinin sanat tarihçileri için önemli olmasının temel nedeni nedir?', 'Sanatçıların adlarını, ücretlerini ve atölyelerini kaydetmesi', ['Sanatçıların yaptığı bütün eserlerin resimlerini tek tek içermesi', 'Padişahların sanat üzerine yazdığı şiirleri toplaması', 'Hat sanatının kurallarını tek tek anlatması'], 'Bu ücret ve inam defterleri hangi sanatçının hangi dönemde sarayda çalıştığını belgeler.'),
  ('Kara Memi\'nin tezhip ettiği ve onun naturalist üslubunun ünlü örneği sayılan eser hangisidir?', 'Muhibbî Divanı', ['Surname-i Vehbi', 'Kitab-ı Bahriye', 'Beyân-ı Menâzil'], 'Kanuni\'nin mahlası Muhibbî\'dir; 1566 tarihli Muhibbî Divanı\'nın tezhibi Kara Memi\'ye aittir.'),
  ('Bir ciltte sayfaların sırt kısmının alt ve üst uçlarına renkli ipliklerle örülen, kitabın formalarını bir arada tutan ve süs de oluşturan örgüye ne ad verilir?', 'Şiraze', ['Sertab', 'Mıklep', 'Kenar suyu'], 'Şiraze, formaları birbirine bağlayan ve sırtın uçlarında renkli bir örgü oluşturan iplik işidir.'),
  ('Bir kütüphaneci, deri kapağın ortasında oyulmuş deriden yapılmış ince bir desenin altına renkli kâğıt ya da kumaş konulduğunu görüyor. Bu süsleme tekniğine ne denir?', 'Katı\' süslemesi', ['Halkâr cilt süslemesi', 'Ebru cilt süslemesi', 'Zerefşan cilt süslemesi'], 'Katı\' tekniğinde deri ya da kâğıt oyulur ve altına farklı renkte zemin konarak desen belirginleştirilir.'),
  ('Hat kıtalarını ve minyatürleri kenar kâğıtlarına ustalıkla ekleyen, yırtık sayfaları onaran sanatçıya ne ad verilir?', 'Vassâl', ['Hakkâk', 'Mücellit', 'Müzehhip'], 'Vassâl \'ekleyen\' demektir; kıtaları ebrulu ya da renkli kenar kâğıtlarına birleştirir.'),
  ('Katı\' sanatında kâğıdın oyulup çıkarılan pozitif ve negatif parçalarının ikisinin de ayrı eserlerde kullanılabilmesi, bu sanatın hangi özelliğini gösterir?', 'Tek kesimden iki tamamlayıcı desen elde edilebilmesini', ['Kâğıdın boyanmadan hiçbir eserde kullanılamamasını', 'Oymanın yalnız kalın deriye uygulanabilmesini', 'Desenin sadece altınla çizilmesini'], 'Oyulan parça ile oyulduğu boşluk birbirinin tersi iki desen sunar; ikisi de ayrı zeminlere yapıştırılabilir.'),
  ('\'Minyatür\' sözcüğü hangi kökenden gelir?', 'Latince kırmızı boya anlamındaki \'minium\'dan', ['Küçük anlamına gelen Arapça bir kökten türeyerek', 'Bir İran şehrinin adından', 'Bir Fransız ressamın soyadından'], 'Ortaçağ Avrupa el yazmalarında başlıklarda kullanılan kırmızı boya minium\'dan türemiştir; Osmanlı\'da bu sanata nakış ya da tasvir denirdi.'),
  ('Minyatürlerde kullanılan geleneksel boyaların bağlayıcısı olarak çoğunlukla hangi madde kullanılırdı?', 'Arap zamkı ya da yumurta akı', ['Keten yağı', 'Akrilik reçine', 'Balmumu ile terebentin karışımı'], 'Toprak ve mineral pigmentler zamk ya da yumurta akıyla bağlanarak sulu boya gibi kullanılırdı.'),
  ('Turfan bölgesindeki Bezeklik mağara tapınaklarının duvar resimleri hangi dinî çevreyle ilişkilidir?', 'Budizm', ['Hristiyanlık', 'Zerdüştlük', 'Yahudilik'], 'Bezeklik bin Buda mağaralarında Uygur dönemine ait Budist duvar resimleri bulunur.'),
  ('Herat okulu ile Osmanlı nakkaşhanesi arasındaki ilişki için hangisi doğrudur?', 'Timurlu ve Safevi ustalar Osmanlı süslemesini etkilemiştir', ['Herat okulu Osmanlı\'dan sonra kurulmuştur', 'Herat ressamları yalnız tuval üzerine yağlıboya kullanmıştır', 'İki gelenek arasında hiçbir bağ yoktur'], 'Tebriz ve Herat\'tan gelen sanatçılar Osmanlı nakkaşhanesinde çalışmış, bulut ve hatayi gibi motifler bu yolla yaygınlaşmıştır.'),
  ('Seyyid Lokman\'ın yazdığı ve padişahların fiziksel özelliklerini anlatan metnin, Nakkaş Osman\'ın çizdiği padişah portreleriyle birleştiği eser hangisidir?', 'Şemâilnâme', ['Surname-i Vehbi', 'Beyân-ı Menâzil', 'Varka ve Gülşah'], 'Şemâilnâme (Kıyafetü\'l-insâniyye) Osmanlı padişahlarının portrelerini ve kısa biyografilerini içerir.'),
  ('1582\'de III. Murad\'ın oğlu Şehzade Mehmed\'in sünnet düğünü için düzenlenen şenliği konu alan resimli eser hangisidir?', 'Surname-i Hümayun', ['Surname-i Vehbi', 'Hünernâme', 'Siyer-i Nebi'], 'At Meydanı\'nda haftalarca süren şenlikte esnaf alayları ve gösteriler resmedilmiştir.'),
  ('Siyah Kalem resimlerini klasik saray minyatürlerinden ayıran özellik hangisidir?', 'Sert çizgili figürlerle göçebe ve doğaüstü konuları işlemesi', ['Yalnız padişah portrelerini içermesi', 'Tamamen altın varaktan oluşması', 'Doğrusal perspektifi Batılı ustalar gibi kusursuz kullanması'], 'Siyah Kalem albümleri saray törenleri yerine göçebeleri, dervişleri ve devleri canlı bir dışavurumla anlatır.'),
  ('Ebru yaparken ikinci ve üçüncü renk boyalara ilk renge göre daha fazla öd katılmasının nedeni nedir?', 'Sonraki boyanın öncekileri itip yer açabilmesi', ['Sonraki boyaların kâğıt üzerinde daha hızlı kuruması', 'Kâğıdın sonraki boyaları emmemesi', 'Boyaların birbirine karışarak yeni renk oluşturması'], 'Daha fazla öd alan boya yüzeyde daha güçlü yayılır ve önceki renkleri sıkıştırarak kendi alanını oluşturur.'),
  ('Türk ebru sanatı UNESCO İnsanlığın Somut Olmayan Kültürel Mirası Temsili Listesi\'ne hangi yıl alınmıştır?', '2014', ['2008', '2011', '2017'], 'Geleneksel Türk ebru sanatı 2014 yılında UNESCO listesine kaydedilmiştir.'),
  ('Bir sanatçı battal zemine iç içe renk damlaları bırakıp bunları bizle biçimlendirerek kalp ve yuvarlak motifler oluşturuyor. Bu yöntem hangi ebru türünü verir?', 'Hatip ebrusu', ['Taraklı ebru', 'Gelgit ebru', 'Şal ebru'], 'Hatip ebrusunda zemin üzerine damlatılan iç içe renkler bizle şekillendirilerek motifler elde edilir.'),
  ('Ebruda kâğıdın bir bölümünün önceden kapatılarak, ebru yapıldıktan sonra o bölümün boş kalmasıyla oluşturulan, içine yazı ya da süsleme yerleştirilen teknik hangisidir?', 'Akkâse', ['Battal', 'Gelgit', 'Neftli'], 'Akkâsede yazı ya da şekil kesilmiş bir maske kâğıda konur; ebrudan sonra kaldırıldığında o alan beyaz kalır.'),
  ('Boya içine az miktarda neft yağı katılarak zeminde ince benekli ve hareli bir görünüm elde edilen ebru türü hangisidir?', 'Neftli ebru', ['Taraklı ebru', 'Bülbül yuvası', 'Çiçekli ebru'], 'Neft yağı boyanın açılmasını değiştirir ve zeminde ince benekler oluşturur.'),
  ('Çiçekli ebrunun ortaya çıkışı ebru sanatına ne kazandırmıştır?', 'Soyut zeminlerin yanında tanınabilir çiçek biçimlerini', ['Ebrunun kâğıt yerine kumaşa uygulanmasını', 'Ebruda öd kullanımının bırakılmasını', 'Ebrunun kâğıt yerine tuval üzerinde yağlıboyayla yapılmasını'], 'Geleneksel ebru türleri genellikle soyut zemindir; çiçekli ebru ile su üzerinde belirgin çiçek biçimleri elde edilmiştir.'),
  ('Sırın içine metal oksitler katılıp fırınlamada metalik bir parlaklık elde edilen tekniğe ne ad verilir?', 'Lüster', ['Sıraltı', 'Mozaik', 'Kakma'], 'Lüster tekniğinde gümüş ve bakır gibi metal tuzları indirgen ortamda pişirilerek altın sarısı bir parıltı verir.'),
  ('Desen alanlarının birbirine karışmaması için konturların yağlı bir maddeyle çizilip aralarına farklı renkte sırlar doldurulduğu teknik hangisidir?', 'Renkli sır', ['Sıraltı mavi-beyaz', 'Lüster', 'Mozaik'], 'Renkli sır tekniğinde konturlar fırında yanarak koyu çizgi bırakır; Bursa Yeşil Cami ve Türbe\'de bu teknik kullanılmıştır.'),
  ('Bir çini ustası mercan kırmızısını kullanırken boyanın hafif kabarık kalmasına dikkat ediyor. Bu kırmızının elde edildiği malzeme hangisidir?', 'Demirli kil', ['Kobalt cevheri', 'Krom tuzları', 'Gümüş nitrat çözeltisi'], 'Mercan kırmızısı demir oksitçe zengin bir kil olan bolüsle yapılır; kalın sürüldüğünden yüzeyde hafif kabartı oluşur.'),
  ('Kubadabad Sarayı çinileri, \'İslam sanatında figür kullanılmaz\' genellemesinin neden doğru olmadığını gösterir?', 'Saray yapılarında figürlü çiniler kullanılmıştır', ['Bu çinilerde hiçbir motif yoktur', 'Bu çiniler Bizans ustalarınca bir cami için yapılıp saraya taşınmıştır', 'Çinilerde yalnız yazı kullanılmıştır'], 'Figür kullanımı dinî yapılarda kaçınılan bir durumdur; saray gibi sivil yapılarda figürlü süsleme yaygındır.'),
  ('Kubadabad çinilerinde birbirine geçecek biçimde birlikte kullanılan iki karo şekli hangisidir?', 'Yıldız ve haç', ['Altıgen ve daire', 'Kare ve düzgün beşgen', 'Üçgen ve oval'], 'Yıldız biçimli figürlü karolar, aralarına giren haç biçimli karolarla bir yüzey oluşturur.'),
  ('Bursa\'daki Yeşil Cami ve Yeşil Türbe çinilerini yapan, Osmanlı\'ya renkli sır tekniğini getirdiği bilinen usta grubu hangi adla anılır?', 'Ustâdân-ı Tebriz', ['Ehl-i hiref Kütahya', 'Şam ustaları', 'Venedik camcıları'], 'Tebrizli ustalar 15. yüzyıl başında Bursa\'da çalışmış; Yeşil Cami\'nin mihrabı ve hünkâr mahfili onların eseridir.'),
  ('Erken Osmanlı döneminde üretilen, kırmızı hamurlu, beyaz astarlı ve sıraltı tekniğiyle bezenmiş seramiklere, ilk kez bulundukları yerden dolayı ne ad verilmiştir?', 'Milet işi', ['Haliç işi', 'Şam işi', 'Rodos işi'], 'Bu seramikler ilk olarak Milet kazılarında bulunduğu için Milet işi denmiş, sonradan İznik\'te de üretildiği anlaşılmıştır.'),
  ('\'Milet işi\' ve \'Rodos işi\' gibi adların seramiklerin gerçek üretim yerini göstermemesi sanat tarihi açısından neyi öğretir?', 'Adların ilk buluntu yerinden gelebildiğini', ['Bu seramiklerin tamamının Yunanistan\'daki atölyelerde üretildiğini', 'İznik\'te hiç çini üretilmediğini', 'Adların ustaların doğum yerini gösterdiğini'], 'Her iki ad da ilk bulundukları ya da toplandıkları yerden gelir; ikisinin de esas üretim merkezi İznik\'tir.'),
  ('İznik seramiklerinde ince spiral dallar ve küçük yapraklarla bezenmiş, önce Haliç kıyısında bulunduğu için yanlış adlandırılan grup hangisidir?', 'Haliç işi', ['Rodos işi', 'Şam işi', 'Kütahya işi'], 'Haliç işi adı İstanbul Haliç\'te bulunan parçalardan gelir; aslında İznik\'te 16. yüzyılın ilk yarısında üretilmiştir.'),
  ('16. yüzyıl ortasında İznik\'te ada çayı yeşili, mor ve firuzenin birlikte kullanıldığı, Suriye\'de üretildiği sanıldığı için yanlış adlandırılan grup hangisidir?', 'Şam işi', ['Haliç işi', 'Milet işi', 'Mavi-beyaz grup'], 'Şam işi bu adı Şam\'da bulunan örneklerden almıştır; esas üretim yeri İznik\'tir.'),
  ('İznik çini tarihini doğru sırayla gösteren dizilim hangisidir?', 'Mavi-beyaz, Şam işi, mercan kırmızılı polikrom', ['Şam işi, mavi-beyaz, mercan kırmızılı polikrom', 'Mercan kırmızılı polikrom, Şam işi, mavi-beyaz', 'Mavi-beyaz, mercan kırmızılı polikrom, Şam işi'], 'İznik\'te önce mavi-beyaz, ardından Şam işi denilen çok renkli grup, sonra 1550\'lerden itibaren mercan kırmızılı polikrom üslup gelişmiştir.'),
  ('Kütahya seramiklerini İznik\'ten ayıran özelliklerden biri hangisidir?', 'Sarının ve serbest çizimin daha sık görülmesi', ['Yalnız lacivert ve beyaz kullanılması', 'Hiç sır kullanılmaması', 'Bütün eserlerde yalnızca mozaik tekniğinin uygulanması'], 'Kütahya işlerinde sarı, yeşil ve mor sıkça görülür; çizimler daha serbest ve halk sanatına yakındır.'),
  ('18. yüzyıl başında İznik ustalarının İstanbul\'a getirilerek bir çini atölyesi kurulduğu Bizans dönemi yapısı hangisidir?', 'Tekfur Sarayı', ['Ayasofya', 'Kariye', 'Yerebatan Sarnıcı'], 'Lale Devri\'nde Tekfur Sarayı\'nda çini atölyesi kurulmuş; burada üretilen çiniler bazı İstanbul yapılarında kullanılmıştır.'),
  ('Kudüs\'teki Kubbetü\'s-Sahra\'nın dış cephesinin hangi Osmanlı padişahı döneminde çinilerle kaplandığı bilinir?', 'Kanuni Sultan Süleyman', ['Yavuz Sultan Selim', 'II. Abdülhamid', 'III. Ahmed'], 'Kanuni döneminde Kubbetü\'s-Sahra\'nın dış cephesindeki mozaikler yerine çini kaplama yapılmıştır.'),
  ('Pazırık halısının Türk düğümüyle dokunmuş olması, halı sanatı tarihi açısından neyi destekleyen bir kanıt sayılır?', 'Düğümlü halının Orta Asya\'da çok eskiye uzandığını', ['Halıcılığın Avrupa\'da doğup ticaret yoluyla Asya\'ya yayıldığını', 'Türk düğümünün 19. yüzyılda icat edildiğini', 'Halıların ilk kez Mısır\'da dokunduğunu'], 'MÖ 5-4. yüzyıldan kalan bu halı, simetrik düğümlü halı tekniğinin Orta Asya\'da çok erken geliştiğini gösterir.'),
  ('Bir sanat tarihçisi, tarihi bilinmeyen bir Anadolu halısını, aynı desenin 1530\'larda yapılmış bir Avrupa tablosunda görüldüğünü tespit ederek tarihliyor. Bu yöntem neye dayanır?', 'Resmin tarihinin desenin o tarihte var olduğunu kanıtlamasına', ['Tablonun halıyla aynı malzemeden yapılmasına', 'Halıların her zaman ressamlar tarafından dokunmasına', 'Avrupalı ressamların bütün halı desenlerini kendi hayal güçleriyle icat etmesine'], 'Avrupa resimlerindeki Türk halıları, desen tiplerinin ne zaman kullanıldığını belirleyen önemli belgelerdir.'),
  ('Kilimlerde iki farklı rengin dikey sınırında, atkıların ayrı çözgülerden geri dönmesiyle oluşan küçük açıklıklara ne ad verilir?', 'Yarık', ['Hav', 'Saçak', 'Kenar örgüsü'], 'Her renk kendi alanında dönerken komşu renkle arasında dikey bir yarık oluşur; bu kilime özgü bir yapıdır.'),
  ('Zemin dokusu yapılırken desenin, ek renkli bir atkının belirli çözgülerin üzerinden atlatılmasıyla kabarık biçimde oluşturulduğu düz dokuma hangisidir?', 'Cicim', ['Kilim', 'Halı', 'Keçe'], 'Cicimde desen zemin dokusunun üzerine eklenen renkli atkılarla yapılır; arka yüzde iplik atlamaları görülür.'),
  ('Ek atkı ipliklerinin belirli aralıklarla çözgülerin üzerinden atlatılarak sık ve düzenli sıralar oluşturduğu, yüzeyin baştan sona küçük desenlerle kaplı göründüğü düz dokuma türü hangisidir?', 'Zili', ['Battaniye', 'Halı', 'Kilim'], 'Zili tekniğinde ek atkılar çözgülerin üzerinden atlatılarak desen oluşturulur; yüzey çoğunlukla tümüyle desenle kaplıdır.'),
  ('Atkı ipliğinin birkaç çözgünün üzerinden geçip bir çözgünün etrafına sarılarak ilerlediği, arka yüzünde iplik uçlarının sarktığı dokuma tekniğine ne ad verilir?', 'Sumak', ['Gördes', 'Kilim', 'Cicim'], 'Sumak bir sarma tekniğidir; ön yüzde balıksırtı görünümlü bir doku oluşur.'),
  ('Bir dokumacı, kilim, cicim ve zili ürünlerini ayırt etmek için hangi soruyu sorarsa en belirleyici bilgiyi alır?', 'Desenin zemin atkısıyla mı ek atkıyla mı yapıldığı', ['Dokumanın kaç metre uzunlukta olduğu', 'Dokumanın hangi mevsimde yapıldığı', 'Dokumacının hangi köyde ve kaç yaşında olduğu ile ailesinin mesleği'], 'Kilimde desen doğrudan zemin atkısıyla oluşur; cicim ve zilide ise ek atkılar desen yapar.'),
  ('Doğal boyamada iplik boyanmadan önce şap gibi maddelerle kaynatılır. Bu işlemin amacı nedir?', 'Boyanın life kalıcı tutunmasını sağlamak', ['İpliği yumuşatıp kısaltmak', 'Yünü ağartıp hayvan kokusunu tamamen gidermek', 'İpliğin rengini tamamen silmek'], 'Mordan adı verilen şap gibi maddeler boya ile lif arasında bağ kurarak rengin kalıcı olmasını sağlar.'),
  ('1981\'de Çanakkale Ayvacık ve Manisa Yuntdağı köylerinde başlatılan ve doğal boyalı halı geleneğini yeniden canlandıran proje hangisidir?', 'DOBAG', ['GAP', 'TÜBİTAK Halı', 'UNESCO Kilim'], 'DOBAG (Doğal Boya Araştırma ve Geliştirme Projesi) Harald Böhmer\'in öncülüğünde köylü kadınlarla doğal boya kullanımını canlandırmıştır.'),
  ('Sinan\'ın Karaboğdan (Moldova) seferi sırasında ordunun geçmesi için kısa sürede inşa ettiği yapı türü hangisidir?', 'Nehir üzerinde köprü', ['Tuna kıyısında kale', 'Karadeniz\'de liman', 'Dağ geçidinde tünel'], '1538 Karaboğdan seferinde Sinan\'ın Prut üzerine kısa sürede kurduğu köprü onun ününü artırmıştır.'),
  ('Şehzade Camii\'nin plan şemasının ayırt edici özelliği hangisidir?', 'Merkezî kubbenin dört yarım kubbeyle desteklenmesi', ['Tek kubbenin sekiz ayağa oturması', 'Hiç kubbe olmayıp ahşap düz tavanla örtülmesi', 'Merkezî kubbenin yalnız iki yarım kubbeyle desteklenmesi'], 'Şehzade Camii\'nde merkezî kubbe dört yarım kubbeyle çevrilir; bu simetrik plan Sinan\'ın ilk büyük denemesidir.'),
  ('Süleymaniye ile Selimiye\'nin kubbe sistemleri karşılaştırıldığında hangisi doğrudur?', 'Süleymaniye iki yarım kubbeli, Selimiye sekiz ayaklı tek kubbelidir', ['İkisinde de merkezî kubbe dört yarım kubbeyle desteklenir', 'Selimiye\'de iki yarım kubbe varken Süleymaniye\'de hiç yarım kubbe yoktur', 'Süleymaniye tek kubbeli küçük bir mescittir'], 'Süleymaniye Ayasofya\'yı andıran iki yarım kubbeli şemayı, Selimiye ise sekiz destekli tek büyük kubbeyi kullanır.'),
  ('Selimiye Camii UNESCO Dünya Mirası Listesi\'ne hangi yıl alınmıştır?', '2011', ['1985', '1999', '2017'], 'Selimiye Camii ve Külliyesi 2011\'de UNESCO Dünya Mirası Listesi\'ne girmiştir.'),
  ('Rüstem Paşa Camii\'nin yüksek bir bodrum katı üzerine yapılmasının ve altında dükkânların yer almasının amacı nedir?', 'Dükkân kiralarıyla caminin giderlerini karşılamak', ['Camiyi sel baskınlarından korumak için yalnız depo yapmak', 'Caminin minaresini yükseltmek', 'Bodrumu medrese olarak kullanmak'], 'Alttaki dükkânların kira gelirleri vakfa gelir sağlar; çarşı içindeki cami böylece yükseltilmiş olur.'),
  ('Kadırga\'daki Sokullu Mehmed Paşa Camii\'nin mihrabı ile ilgili ünlü özellik hangisidir?', 'Mihrapta Kâbe\'den getirilen taş parçaları bulunması', ['Mihrabın tamamen ahşaptan yapılması', 'Mihrabın caminin dışında, son cemaat yerinde yer alması', 'Mihrapta hiç süsleme olmaması'], 'Sokullu Camii\'nde mihrap, minber ve giriş üzerinde Hacerülesved\'den getirildiği bilinen parçalar bulunur; mihrap duvarı İznik çinileriyle kaplıdır.'),
  ('Tophane\'de bulunan ve plan bakımından küçük ölçekli bir Ayasofya\'yı andıran Sinan camisi hangisidir?', 'Kılıç Ali Paşa Camii', ['Şehzade Camii', 'Mihrimah Sultan Camii', 'Atik Valide Camii'], 'Kaptan-ı derya Kılıç Ali Paşa için yapılan cami, Ayasofya\'nın plan şemasını küçültülmüş ölçekte yorumlar.'),
  ('Sinan\'ın Şam\'da Kanuni adına yaptığı, cami ve tekke yapılarından oluşan külliye hangisidir?', 'Süleymaniye Tekkesi', ['Emevi Camii', 'Azm Sarayı', 'Kubbetü\'s-Sahra'], 'Şam\'daki Süleymaniye Külliyesi Sinan\'ın İstanbul dışındaki önemli eserlerindendir.'),
  ('Vişegrad Köprüsü\'nü konu alan \'Drina Köprüsü\' adlı romanın yazarı olan ve 1961 Nobel Edebiyat Ödülü\'nü alan yazar kimdir?', 'İvo Andriç', ['Meşa Selimoviç', 'Danilo Kiş', 'Ismail Kadare'], 'İvo Andriç romanında köprüyü yüzyıllar boyunca değişen toplumun tanığı olarak anlatır.'),
  ('İstanbul\'un Büyükçekmece\'sinde göl ağzı üzerinde Sinan\'ın yaptığı, birbirine adacıklarla bağlanan dört bölümden oluşan köprü hangisidir?', 'Kanuni Sultan Süleyman Köprüsü', ['Uzunköprü', 'Sokullu Mehmed Paşa Köprüsü', 'Haliç üzerindeki Galata Köprüsü'], 'Büyükçekmece\'deki bu köprü 1567\'de tamamlanmış, dört bölüm ve çok sayıda kemerden oluşur.'),
  ('Alibeyköy deresi vadisini aşan, iki katlı kemerleriyle Sinan\'ın su mühendisliğinin en etkileyici örneklerinden sayılan yapı hangisidir?', 'Mağlova Kemeri', ['Bozdoğan Kemeri', 'Galata Kulesi', 'Yerebatan Sarnıcı'], 'Mağlova Kemeri Kırkçeşme suyolunun bir parçasıdır; Bozdoğan (Valens) Kemeri ise Roma dönemine aittir.'),
  ('Sinan\'ın ardından mimarbaşı olan ve Eminönü\'ndeki Yeni Cami\'nin inşasına başlayan mimar kimdir?', 'Davud Ağa', ['Sedefkâr Mehmed Ağa', 'Mimar Kemaleddin', 'Kasım Ağa'], 'Davud Ağa 1588\'den sonra mimarbaşı olmuş, Yeni Cami\'nin temellerini atmıştır; cami çok sonra tamamlanmıştır.'),
  ('Mimar Sinan\'a atfedilen eser sayısının kaynaklarda farklı verilmesinin en makul nedeni hangisidir?', 'Onarılan ve denetlenen yapıların farklı biçimde sayılması', ['Sinan\'ın eserlerinin çoğunun yer altında olması', 'Sinan\'ın eserlerini rakiplerinden gizli tutup kayıt düşmemesi', 'Sinan\'ın hiçbir eserinin kayda geçmemesi'], 'Farklı tezkirelerde onarım, ek ve ocak yönetimindeki yapılar farklı biçimde sayıldığı için sayı değişir.'),
  ('Gümüş yüzeye kazınan desenlerin içine kurşun, bakır ve kükürt karışımı siyah bir alaşımın doldurulmasıyla yapılan süsleme tekniğine ne ad verilir?', 'Savat', ['Tombak', 'Telkâri', 'Lüster'], 'Savat işinde siyah dolgu gümüş zeminde belirgin bir kontrast yaratır; Van ve Erzurum\'da yaygındır.'),
  ('Bir kuyumcu, gümüş bir tabakayı arka yüzünden dövüp ön yüzde yükselen desenler elde ediyor. Bu yöntemin adı nedir?', 'Kabartma', ['Telkâri', 'Kalıba döküm', 'Kakma'], 'Metalin arka yüzden dövülerek ön yüzde kabarık desen elde edilmesi kabartma tekniğidir.'),
  ('Mukarnasın bir kare mekândan kubbeye geçişte kullanılması onun hangi işlevini gösterir?', 'Hem süsleme hem geçiş öğesi olmasını', ['Yalnız yağmur suyunu tahliye etmesini', 'Yapının yangına dayanıklılığını artırmasını', 'Yalnızca ibadet sırasında ses yalıtımı sağlamasını'], 'Mukarnas, köşelerdeki boşlukları kademeli olarak doldurarak kare plandan dairesel kubbeye geçişi sağlar.'),
  ('Minyatür sanatında bir figürün yüzünün çoğunlukla dörtte üç profilden çizilmesinin amacı ne olabilir?', 'Yüzü tanınır kılıp sahneye hareket katmak', ['Işık-gölge uygulamasını kolaylaştırmak', 'Ressamın kimliğini izleyiciden gizlemek', 'Figürün öldüğünü göstermek'], 'Yarı profil yüz hem yüz hatlarını gösterir hem de figürler arasında bakışma ve etkileşim yaratır.'),
  ('Bir restoratör bir camideki çini panoda tek bir karonun desenine bakarak eksik karoyu tamamlamak istiyor. Bunun mümkün olmasının nedeni nedir?', 'Panonun karolara bölünmüş tek bir desen olması', ['Her karonun bağımsız ve rastgele desenli olması', 'Çinilerin hiç desen taşımaması', 'Karoların tamamen tek renkli olması'], 'Çini panolar nakkaşın çizdiği bir bütün desenin karolara bölünmesiyle oluşur; komşu karolar eksik parçayı tamamlamaya yol gösterir.'),
  ('Firuze renkli çinilerde rengi veren temel metal oksit hangisidir?', 'Bakır oksit', ['Kobalt oksit', 'Kalay oksit', 'Krom oksit'], 'Bakır oksit alkali sırlarda firuze rengi verir; kobalt ise lacivert mavi tonlar oluşturur.'),
  ('Bir çini karoda beyaz zemin elde etmek için sırın içine katılan ve onu opaklaştıran madde hangisidir?', 'Kalay oksit', ['Kobalt oksit', 'Demir oksit', 'Mangan oksit'], 'Kalay oksit sırı beyazlatıp opaklaştırır; böylece altındaki hamurun rengi örtülür.'),
  ('Bir koleksiyoncu, kenarları ve köşeleri motiflerle tamamlanmamış, kesik desenli bir halı görüyor. Bu durum hangi tasarım anlayışına işaret eder?', 'Desenin sınırların dışında sürdüğü sonsuz desen anlayışına', ['Dokumacının işi yarıda bırakıp tezgâhtan kestiğine', 'Halının sonradan kesildiğine kesin kanıt olduğuna', 'Halının yalnız duvar için dokunduğuna'], 'Sonsuz tekrar anlayışında desen alanı kenarlarda kesilir; izleyici desenin dışarıda devam ettiğini sezer.'),
  ('Sinan\'ın yapılarında kubbe yükünü taşıyan ayakların ve payandaların dışarıda belirgin olmayacak biçimde duvarlara gömülmesi neyi amaçlar?', 'İç mekânı bölmeden yükü taşımak', ['Yapının dışarıdan daha ağır ve kalın görünmesini sağlamak', 'Pencere sayısını azaltmak', 'Minareleri gizlemek'], 'Sinan taşıyıcı öğeleri ustaca gizleyerek iç mekânda ferah ve bütünleşik bir hacim elde etmiştir.'),
  ('Selimiye Camii\'nde müezzin mahfilinin kubbenin tam altında, iç mekânın ortasında yer alması nasıl yorumlanabilir?', 'Mekânın merkezinin vurgulanması', ['Mihrabın kaldırıldığının gösterilmesi', 'Caminin iki ayrı bölüme ayrılması', 'Kubbenin çökmesini engelleyen tek taşıyıcı destek olması'], 'Selimiye\'de merkezi kubbe altındaki mahfil, mekânın merkezîliğini güçlendiren bir tasarım tercihidir.'),
  ('Sinan\'ın Selimiye\'de sekiz ayak üzerine oturttuğu kubbe planı ile Şehzade\'deki dört yarım kubbeli plan arasındaki gelişme en iyi nasıl özetlenir?', 'Bölünmüş mekândan tek kubbeli bütünleşik mekâna', ['Tek büyük kubbeden çok sayıda küçük kubbeye doğru bir geçiş', 'Kubbeli yapıdan düz damlı yapıya doğru', 'Taş yapıdan ahşap yapıya doğru'], 'Sinan\'ın arayışı yarım kubbeleri azaltıp iç mekânı tek bir büyük kubbe altında birleştirmeye yöneliktir.'),
  ('Osmanlı\'da yastık ve döşemelerde kullanılan, havlı yüzeyli ipek kadifeye ne ad verilir?', 'Çatma', ['Kemha', 'Seraser', 'Basma'], 'Çatma havlı bir ipek kadifedir; Bursa ve Üsküdar bu kumaşın üretim merkezleri arasındadır.'),
  ('Bir hattat, geleneksel bir sülüs istifini Latin harfleriyle taklit etmeye çalışıyor ama aynı etkiyi elde edemiyor. Bunun en olası nedeni nedir?', 'Arap harflerinin bağlanıp uzayabilmesi', ['Latin harflerinin hiç yazılamaması', 'Mürekkebin Latin harflerine uymaması', 'Kamış kalemin yalnız Arapça yazması'], 'Arap harflerinin kelime içinde birleşmesi, uzayıp kısalabilmesi istif yapmaya imkân verir; Latin harflerinde bu esneklik sınırlıdır.'),
  ('Bir halı uzmanı bir köy kilimi ile bir saray halısını incelerken köy kiliminde motiflerin köşeli, saray halısında eğri hatlı olduğunu görüyor. Bu farkın teknik açıklaması hangisidir?', 'Düz dokumada eğri çizginin zor olması', ['Köy dokumacılarının eğri çizgiyi sevmemesi', 'Saray halılarının tamamının buharlı makinelerle dokunması', 'Kilimlerin boyasız yapılması'], 'Kilimde desen çözgü ve atkıların dik kesişmesiyle oluştuğundan basamaklı ve köşeli olur; ince düğümlü halılar eğri hatlara izin verir.'),
];
